};

type GenericTooltipState = {
    /** Is tooltip visible */
    isVisible: boolean;

    /** Show tooltip */
    showTooltip: () => void;

    /** Hide tooltip */
    hideTooltip: () => void;

    /** Update the tooltip's target bounding rectangle */
